// Generated by scripts/gen-manifest.ts. Do not edit by hand.
// Templates are compiled in as strings: never fetched.
export const bundledTemplates: { id: string; text: string }[] = [
  { id: "azul", text: "# azul.gamebuddy — draft tiles, fill a wall\n\n[game]\nname: Azul\nplayers: 2-4\ntime: 40m\ntags: board, puzzle\nsource: https://boardgamegeek.com/boardgame/230802/azul\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a player board\n- Fill the round factory displays with four tiles each\n- Put the first player marker in the middle\n- Shuffle the bag\n\n[rules]\nTake tiles from a factory, place them on a pattern line, then score when the line completes.\n- A completed line scores its tile and every connected tile on the wall\n- Floor tiles cost points\n- The game ends when a player completes a row\n- Add end-of-game bonuses; the highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "catan", text: "# catan.gamebuddy — victory points on the table, not on scrap paper\n\n[game]\nname: Catan\nplayers: 3-4\ntime: 90m\ntags: board, strategy\nsource: https://www.catan.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the hexes, ring the board with sea and place the desert\n- Shuffle the number tokens onto the hexes in order\n- Place one settlement and road per player in turn, then a second pair in reverse\n- Take the starting resources from the second settlement\n\n[rules]\nRace to 10 victory points. Settlements are 1 point, cities 2, longest road and largest army 2 each, and a few development cards add a point.\n- Roll for resources, trade, then build\n- The first player to reach 10 points on their own turn wins\n- Track the counts here; the totals follow the category points\n\n[tool score]\nmode: categories\ncategories: settlements=1, cities=2, longest-road=2, largest-army=2, cards=1\ntarget: 10\nwin: highest\n" },
  { id: "chess-blitz", text: "# chess-blitz.gamebuddy — two clocks, one increment\n\n[game]\nname: Chess / Blitz\nplayers: 2\ntime: 10-60m\ntags: board, duel\nsource: https://www.fide.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Set up the board with the queen on her own colour\n- Agree on the time control, for example five minutes plus three seconds\n- Decide who plays white\n- Put the clocks where both players can reach them\n\n[rules]\nStandard chess. Checkmate wins; a flag fall loses on time.\n- White moves first, then players alternate\n- The clock only runs for the player to move\n- Tap the clock to hand the turn over; the increment is added\n- Resign, draw or checkmate ends the game\n\n[tool timer]\nmode: chess\nduration: 5m\nplayers: 2\nincrement: 3s\nsound: bell\nhaptic: short\n" },
  { id: "coup", text: "# coup.gamebuddy — two influences and a pile of coins\n\n[game]\nname: Coup\nplayers: 2-6\ntime: 15m\ntags: party, bluffing\nsource: https://boardgamegeek.com/boardgame/131357/coup\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the role deck and deal two face-down cards to each player\n- Give every player two coins\n- Put the rest of the deck face down as the court deck\n\n[rules]\nBluff your way to being the last player with influence.\n- Coins buy actions: income, foreign aid, coup and character powers\n- Anyone may challenge a claim; the loser loses an influence\n- Track coins as ledger entries and influences with the lives tool\n- The last player with a face-down card wins\n\n[tool lives]\nmode: players\nlives: 2\nmax: 2\nelimination: yes\n\n[tool score]\nmode: ledger\n\n[tool reveal]\nmode: roles\nroles: duke=3, assassin=3, captain=3, ambassador=3, contessa=3\ndescriptions: duke=Take three coins as tax, assassin=Pay three to assassinate, captain=Steal two coins, ambassador=Swap cards with the court, contessa=Blocks assassination\nauto-hide: 6\n" },
  { id: "decrypto", text: "# decrypto.gamebuddy — clues, interceptions and a two minute clock\n\n[game]\nname: Decrypto\nplayers: 3-8\ntime: 30m\ntags: party, deduction\nsource: https://www.scorpionmasque.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Split into two teams and sit so each team shares a screen\n- Deal four keyword cards to each team\n- Give each team a code card and a pen\n- Put the interception tokens where both teams can reach them\n\n[rules]\nGive clues that point at your keywords without giving them away.\n- The clue giver writes a three number code, then says three clues\n- Their team guesses which keyword matches each number\n- The other team may try to intercept the code\n- Two interceptions or two miscommunications end the game; log tokens per team here\n\n[tool timer]\nmode: countdown\nduration: 2m\nsound: bell\nstart: manual\n\n[tool score]\nmode: ledger\nwin: lowest\n\n[tool reveal]\nmode: ballot\nballot: Did the other team intercept?\noptions: Intercepted, Missed\n" },
  { id: "dixit", text: "# dixit.gamebuddy — one sentence, six pictures, one guess\n\n[game]\nname: Dixit\nplayers: 3-6\ntime: 30m\ntags: party, cards\nsource: https://www.libellud.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal six cards to each player\n- Give every player a voting dial or tokens\n- Shuffle the rest of the deck as the draw pile\n\n[rules]\nThe storyteller says a sentence about a card, everyone else adds a card, then the table votes.\n- Score three points if your card is guessed\n- The storyteller scores if some but not all players guess their card\n- Everyone who votes for the storyteller's card scores too\n- First to 30 points wins\n\n[tool score]\nmode: simple\ntarget: 30\nwin: highest\n\n[tool reveal]\nmode: ballot\nballot: Was the storyteller found?\noptions: Found, Missed\n" },
  { id: "dnd-5e-combat", text: "# dnd-5e-combat.gamebuddy — initiative, hit points and dice macros\n\n[game]\nname: D&D 5e combat\nplayers: 3-7\ntime: varies\ntags: rpg, combat\nsource: https://dnd.wizards.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Roll initiative for every combatant and write the order\n- Note each character's maximum hit points\n- Put the dice where everyone can reach them\n- Agree on how long a turn may take\n\n[rules]\nCombat runs in rounds. Each turn has movement, one action and possibly a bonus action.\n- Roll initiative once; highest goes first\n- Attack, cast or dash as your action\n- Track hit points and conditions here\n- The fight ends when one side is down or flees\n\n[tool turns]\nphases: Action, Bonus action, Move, End\ntimer: 1m\npass: no\nauto-start: no\n\n[tool lives]\nmode: players\nlives: 30\nmax: 60\nelimination: yes\n\n[tool dice]\nroll: 1d20\nmacros: attack=1d20+5, damage=2d6+3, save=1d20\n" },
  { id: "dominion", text: "# dominion.gamebuddy — deck building and victory cards\n\n[game]\nname: Dominion\nplayers: 2-4\ntime: 30m\ntags: card, deckbuilder\nsource: https://www.riograndegames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Lay out ten kingdom cards plus the base treasures and victory cards\n- Give every player a starting deck: seven coppers and three estates\n- Shuffle and draw five cards\n- Put the trash pile in the middle\n\n[rules]\nEach turn: action, buy, clean up, draw five.\n- Treasures buy cards; kingdom cards change the rules\n- The game ends when the province pile or three other piles run out\n- Count victory points: provinces 6, duchies 3, estates 1, curses -1\n- The highest total wins\n\n[tool score]\nmode: categories\ncategories: provinces=6, duchies=3, estates=1, curses=-1\nwin: highest\n\n[tool turns]\nphases: Action, Buy, Cleanup\n" },
  { id: "gloomhaven", text: "# gloomhaven.gamebuddy — initiative, hit points and loot\n\n[game]\nname: Gloomhaven\nplayers: 1-4\ntime: 90m\ntags: rpg, campaign\nsource: https://cephalofair.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a scenario and lay out the map tiles\n- Place monsters and treasure as the scenario says\n- Choose two ability cards per character\n- Shuffle the monster ability deck\n\n[rules]\nA scenario is a series of rounds. Everyone picks two cards, then acts in initiative order.\n- Track hit points with the lives tool\n- Gold and experience go in the ledger as they are earned\n- A short rest or long rest costs a turn\n- Complete the scenario goal to win\n\n[tool lives]\nmode: players\nlives: 10\nmax: 30\nelimination: yes\n\n[tool score]\nmode: ledger\n\n[tool turns]\nphases: Initiative, Player, Monster, End\n" },
  { id: "hanabi", text: "# hanabi.gamebuddy — a cooperative fireworks show\n\n[game]\nname: Hanabi\nplayers: 2-5\ntime: 25m\ntags: card, cooperative\nsource: https://boardgamegeek.com/boardgame/98778/hanabi\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the fireworks deck and deal four or five cards to each player\n- Hold your cards facing the other players\n- Put the fuse and information tokens in the middle\n\n[rules]\nBuild five fireworks from one to five without seeing your own cards.\n- A turn is one action: play a card, discard a card or give a clue\n- Clues cost information tokens; discards refill them\n- Three fuses end the game\n- Score the highest card in each completed firework; 25 is perfect\n\n[tool score]\nmode: simple\ntarget: 25\nwin: highest\n\n[tool timer]\nmode: up\nsound: none\n" },
  { id: "kitchen-rush-timers", text: "# kitchen-rush-timers.gamebuddy — one hourglass per cook\n\n[game]\nname: Kitchen Rush\nplayers: 2-4\ntime: 45m\ntags: board, realtime\nsource: https://boardgamegeek.com/boardgame/224783/kitchen-rush\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player an hourglass timer\n- Shuffle the order deck and deal the opening orders\n- Put the ingredients within reach of the whole table\n- Start the shift together\n\n[rules]\nA realtime cooperative kitchen. Your hourglass is your worker.\n- Flip your timer to take actions while it runs\n- When it empties, you must stop and wait for someone to flip it again\n- Complete orders before the shift ends\n- Track coins and wasted ingredients in the counters tool\n\n[tool timer]\nmode: flip\nduration: 90s\nper-player: yes\nplayers: 4\nlayout: grid\nsound: bell\nhaptic: short\n\n[tool counters]\ncounters: coins=0, wasted=0\nbank: 0\n" },
  { id: "love-letter", text: "# love-letter.gamebuddy — tokens of affection, one card in hand\n\n[game]\nname: Love Letter\nplayers: 2-4\ntime: 20m\ntags: card, deduction\nsource: https://www.zmangames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the sixteen card deck and remove one card face down\n- Deal one card to each player\n- Put the remaining cards face down as the draw pile\n- Give the first player the tokens of affection\n\n[rules]\nDraw one card, play one card, knock players out until one is left.\n- Each card has a number and an effect; guards guess a card\n- The last player in the round wins a token of affection\n- Play until someone has four tokens\n- Add a point per round win here\n\n[tool score]\nmode: simple\ntarget: 4\nwin: highest\n" },
  { id: "monopoly", text: "# monopoly.gamebuddy — cash on the ledger, pieces in the bank\n\n[game]\nname: Monopoly\nplayers: 2-6\ntime: 120m\ntags: board, family\nsource: https://www.hasbro.com/en-us/product/monopoly\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player 1500 in cash\n- Shuffle the chance and community chest decks\n- Put the houses and hotels in the bank\n- Each player picks a token and starts on go\n\n[rules]\nBuy, trade and charge rent until one player is left solvent.\n- Every player starts at 1500; add salary and rent, subtract purchases and fines\n- The houses and hotels counter tracks what is left in the bank\n- Highest cash is a useful tie-breaker if you stop early\n\n[tool score]\nmode: ledger\nstart: 1500\nwin: highest\n\n[tool counters]\ncounters: houses=32, hotels=12\nbank: 0\n\n[tool turns]\nphases: Roll, Buy, Build, End\n" },
  { id: "mtg", text: "# mtg.gamebuddy — twenty life, poison and commander damage\n\n[game]\nname: Magic: the Gathering\nplayers: 2-4\ntime: 30m\ntags: card, duel\nsource: https://magic.wizards.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle your decks and draw seven cards\n- Start at 20 life, or 40 in Commander\n- Agree on mulligans and who plays first\n- Keep a turn timer if the table tends to stall\n\n[rules]\nCast spells, summon creatures and reduce your opponents to zero life.\n- Life goes down and up; use the lives tool\n- Poison counters and commander damage are tracked separately\n- A player with ten poison counters loses\n- Last player standing wins\n\n[tool lives]\nmode: players\nlives: 20\nmax: 40\nelimination: yes\n\n[tool counters]\ncounters: poison=0, commander=0, treasures=0\nbank: 0\n\n[tool timer]\nmode: countdown\nduration: 2m\nsound: bell\nstart: manual\n" },
  { id: "pandemic", text: "# pandemic.gamebuddy — cubes, outbreaks and a ticking clock\n\n[game]\nname: Pandemic\nplayers: 2-4\ntime: 45m\ntags: board, cooperative\nsource: https://www.zmangames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a role card and a pawn\n- Place three cubes of each colour on the starting cities\n- Shuffle the infection deck and infect nine cities\n- Put the outbreak and cure markers within reach\n\n[rules]\nA cooperative race to cure four diseases before the world runs out of time.\n- Each turn: four actions, then draw cards, then infect cities\n- The infection rate rises with every outbreak\n- Five outbreaks or running out of cubes loses the game\n- Track the cube supply and outbreaks here; cure all four to win\n\n[tool counters]\ncounters: red=24, yellow=24, blue=24, black=24, outbreaks=0\nbank: 0\n\n[tool timer]\nmode: up\nsound: none\n" },
  { id: "perudo", text: "# perudo.gamebuddy — dice under cups and escalating bids\n\n[game]\nname: Perudo / Liar's Dice\nplayers: 2-6\ntime: 30m\ntags: dice, bluffing\nsource: https://boardgamegeek.com/boardgame/45/perudo\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a cup and five dice\n- Agree on the starting player\n- Everyone rolls and peeks under their own cup\n\n[rules]\nBid on how many dice of a face are on the table, then call the bluff.\n- A bid is a quantity and a face; each bid must raise the last\n- Calling a bid reveals every cup; the loser loses a die\n- Ones are wild unless someone has bid them\n- Last player with dice wins; use lives and blind bids here\n\n[tool dice]\nroll: 1d6\npool: 5d6\nmacros: cup=5d6\n\n[tool lives]\nmode: players\nlives: 5\nmax: 5\nelimination: yes\n\n[tool reveal]\nmode: bid\nmin-bid: 1\nmax-bid: 30\n" },
  { id: "phase-10", text: "# phase-10.gamebuddy — ten phases, lowest score wins\n\n[game]\nname: Phase 10\nplayers: 2-6\ntime: 45m\ntags: card, family\nsource: https://www.mattelgames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal ten cards to each player\n- Turn one card face up for the discard pile\n- Put the phase cards where everyone can see the ten goals\n\n[rules]\nEach round has one phase to complete, from two sets of three up to a run of nine.\n- Complete your phase, then go out by discarding your last card\n- Cards left in hand count against you\n- Penalty points go in the next round cell\n- The lowest total after ten rounds wins\n\n[tool score]\nmode: rounds\nrounds: 10\nwin: lowest\nstep: 5\n" },
  { id: "poker-night", text: "# poker-night.gamebuddy — stacks, a pot and blind levels\n\n[game]\nname: Poker Night\nplayers: 2-9\ntime: 180m\ntags: card, betting\nsource: Traditional game — no official source\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Agree on a buy-in and give everyone the same starting stack\n- Put the chip bank in the middle\n- Set the blind level timer\n- Deal for the button\n\n[rules]\nTexas Hold'em: two hole cards, five community cards, best hand wins the pot.\n- Track each stack with a ledger entry; start everyone at the same number\n- The shared bank holds the pot and the chips not in play\n- Blind levels go up on the interval timer\n- Blind bids record secret all-in amounts\n\n[tool score]\nmode: ledger\nstart: 1000\nwin: highest\n\n[tool counters]\ncounters: pot=0\nbank: 1000\ndenominations: 1, 5, 25, 100\n\n[tool turns]\nphases: Preflop, Flop, Turn, River, Showdown\n\n[tool reveal]\nmode: bid\nmin-bid: 0\nmax-bid: 10000\n\n[tool timer]\nmode: interval\ninterval: 15m\nsound: bell\n" },
  { id: "risk", text: "# risk.gamebuddy — reinforcements, attacks and fortifying\n\n[game]\nname: Risk\nplayers: 2-6\ntime: 120m\ntags: board, war\nsource: https://www.hasbro.com/en-us/product/risk\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal out the territory cards and place one army on each\n- Players take turns placing their remaining armies\n- Shuffle the territory deck and deal a starting hand\n\n[rules]\nTake over the world one territory at a time.\n- Reinforce from your territories and continent bonuses\n- Attack with up to three dice against up to two defenders\n- Fortify once at the end of your turn\n- Track each player's army count as a ledger entry; the last player standing wins\n\n[tool score]\nmode: ledger\n\n[tool counters]\ncounters: reinforcements=0\nbank: 0\n\n[tool turns]\nphases: Reinforce, Attack, Fortify\n\n[tool dice]\nroll: 3d6\nmacros: attacker=3d6, defender=2d6\n" },
  { id: "seven-wonders", text: "# seven-wonders.gamebuddy — seven kinds of points\n\n[game]\nname: 7 Wonders\nplayers: 3-7\ntime: 45m\ntags: board, strategy\nsource: https://www.rprod.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal a wonder board and three coins to each player\n- Shuffle the three age decks separately\n- Put the military conflict tokens within reach\n\n[rules]\nThree ages of card drafting. Every card is played, sold or used to build a wonder.\n- Military wins beat neighbours\n- Science sets score by their combinations\n- Coins, civilian buildings, commerce and guilds all add points\n- Add up everything at the end; the highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "skull", text: "# skull.gamebuddy — place a rose, make a bid, flip the skulls\n\n[game]\nname: Skull\nplayers: 3-6\ntime: 20m\ntags: party, bluffing\nsource: https://boardgamegeek.com/boardgame/92415/skull\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player one mat and four discs: three roses and one skull\n- Agree on a starting player\n- Keep the discs hidden from the other players\n\n[rules]\nTwo phases: place discs face down, then bid on how many you can flip.\n- The highest bidder flips that many discs, starting with their own\n- One skull ends the attempt and costs a disc\n- Two successful bids win the game\n- Use the blind bid tool for the bidding and the scorepad for wins\n\n[tool reveal]\nmode: bid\nmin-bid: 1\nmax-bid: 8\n\n[tool score]\nmode: simple\ntarget: 2\nwin: highest\n" },
  { id: "splendor", text: "# splendor.gamebuddy — gems, cards and fifteen points\n\n[game]\nname: Splendor\nplayers: 2-4\ntime: 30m\ntags: board, engine\nsource: https://www.spacecowboys.fr/splendor\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the three development decks and lay out four of each\n- Give every player a starting tile\n- Sort the gem tokens by colour\n- Reveal five nobles\n\n[rules]\nCollect gems, buy development cards and attract nobles.\n- A turn is one action: take gems, reserve a card or buy a card\n- Cards give permanent discounts and points\n- Nobles visit at fifteen points of card bonuses\n- First to fifteen points wins; the gem counters track the bank\n\n[tool score]\nmode: simple\ntarget: 15\nwin: highest\n\n[tool counters]\ncounters: emerald=7, sapphire=7, ruby=7, diamond=7, onyx=7, gold=5\nbank: 0\n" },
  { id: "sushi-go", text: "# sushi-go.gamebuddy — three quick rounds of card picking\n\n[game]\nname: Sushi Go!\nplayers: 2-5\ntime: 20m\ntags: card, party\nsource: https://gamewright.com/product/Sushi-Go\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal the right number of cards per player\n- Agree on who starts the first pass\n- Keep the pudding cards visible; they score at the end\n\n[rules]\nPick one card, pass the rest, repeat. Three rounds in total.\n- Maki rolls, tempura, sashimi and dumplings score in their own ways\n- Pudding is scored after the last round\n- Add each round here; the highest total wins\n\n[tool score]\nmode: rounds\nrounds: 3\nwin: highest\n" },
  { id: "the-mind", text: "# the-mind.gamebuddy — play the cards in order without talking\n\n[game]\nname: The Mind\nplayers: 2-4\ntime: 20m\ntags: party, cooperative\nsource: https://www.pandasaurusgames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck of 1 to 100 cards\n- Deal one card per player for level one\n- Put the lives and throwing stars in the middle\n- Agree that nobody may talk about their cards\n\n[rules]\nEveryone holds numbered cards. Play them in ascending order without speaking.\n- Any card played out of order costs a life\n- Clear the level and deal one more card per player\n- A throwing star lets the table discard the lowest card\n- Lose all lives and the run ends; track them here\n\n[tool lives]\nmode: shared\nlives: 3\nmax: 5\nstep: 1\nelimination: yes\n\n[tool counters]\ncounters: shurikens=1\nbank: 0\n" },
  { id: "ticket-to-ride", text: "# ticket-to-ride.gamebuddy — routes, tickets and the longest path\n\n[game]\nname: Ticket to Ride\nplayers: 2-5\ntime: 60m\ntags: board, strategy\nsource: https://www.daysofwonder.com/tickettoride/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player 45 trains and a matching score marker\n- Deal three destination tickets and keep at least two\n- Shuffle the train deck and deal five cards to each player\n- Lay out the five face-up cards\n\n[rules]\nClaim routes by spending matching train cards, then score at the end.\n- A route is worth its printed points\n- Destination tickets add or subtract their value if completed\n- The longest continuous path is worth 10 bonus points\n- The highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n\n[tool turns]\nphases: Draw, Play, End\ntimer: 0s\npass: no\n" },
  { id: "wingspan", text: "# wingspan.gamebuddy — birds, bonuses and round goals\n\n[game]\nname: Wingspan\nplayers: 1-5\ntime: 70m\ntags: board, engine\nsource: https://stonemaiergames.com/games/wingspan/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a player mat, eight action cubes and five food\n- Deal five bird cards and keep any you can afford\n- Shuffle the bird deck and lay out the tray\n- Reveal the first round goal\n\n[rules]\nBuild an engine of birds across four rounds. Each turn is one action: play a bird, gain food, lay eggs or draw cards.\n- Birds score their printed points\n- Bonus cards and round goals add points\n- Eggs, cached food and tucked cards score at the end\n- The highest total after round four wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "yahtzee", text: "# yahtzee.gamebuddy — thirteen categories and five dice\n\n[game]\nname: Yahtzee\nplayers: 2-6\ntime: 30m\ntags: dice, score\nsource: https://www.hasbro.com/en-us/product/yahtzee\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a score sheet and a pen\n- Put five dice and the cup in the middle\n- Agree on the order of play\n\n[rules]\nRoll up to three times, keeping any dice, then score one empty category.\n- Upper section counts the matching faces; 63 or more is a 35 point bonus\n- Lower section has three and four of a kind, full house, small and large straight, Yahtzee and chance\n- The highest total after thirteen rounds wins\n\n[tool dice]\nroll: 5d6\n\n[tool score]\nmode: rounds\nrounds: 13\nwin: highest\n" },
];
